def transform(grid):
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    # Colored objects form a chain. Emit each object's cells in chain order.
    # Find connected monochromatic components and join different-colored touching components.
    h,w=len(grid),len(grid[0])
    cells={(r,c) for r in range(h) for c in range(w) if grid[r][c]!=bg}
    objs=[]
    while cells:
        seed=min(cells); color=grid[seed[0]][seed[1]]
        cells.remove(seed); comp={seed}; stack=[seed]
        while stack:
            r,c=stack.pop()
            for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if p in cells and grid[p[0]][p[1]]==color:
                    cells.remove(p); comp.add(p); stack.append(p)
        objs.append(comp)
    remaining=set(range(len(objs))); current=min(remaining, key=lambda i:min(objs[i])); order=[]
    while remaining:
        order.append(current); remaining.remove(current)
        if not remaining: break
        def touches(i,j):
            return any(abs(r-x)+abs(c-y)==1 for r,c in objs[i] for x,y in objs[j])
        near=[i for i in remaining if touches(current,i)]
        current=near[0] if near else min(remaining,key=lambda i:min(objs[i]))
    return [[grid[min(objs[i])[0]][min(objs[i])[1]]] for i in order for _ in objs[i]]
''')
